<?php

use App\Models\User;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Route;

Route::redirect('/', '/admin');

// One-time login link generated by the bot's /web command.
Route::get('/login/telegram/{user}', function (User $user) {
    abort_unless(Cache::add('web-login:'.request('nonce'), true, now()->addHour()), 403, 'Ссылка уже использована');

    Auth::login($user, remember: true);
    request()->session()->regenerate();

    return redirect('/admin');
})->middleware(['web', 'signed', 'throttle:10,1'])->name('login.telegram');
